                        result = (
                            AIMessage(content="done")
                            if any(isinstance(m, ToolMessage) for m in messages)
                            else AIMessage(
                                content="",
                                tool_calls=[
                                    {
                                        "name": "task",
                                        "args": {
                                            "description": name,
                                            "subagent_type": "general-purpose",
                                        },
                                        "id": "dispatch-" + name,
                                        "type": "tool_call",
                                    }
                                    for name in ("alpha", "beta")
                                ],
                            )
                        )
                    else:
                        inputs[human] = [m.content for m in messages]
                        entered.add(human)
                        if len(entered) == 2:
                            ready.set()
                        try:
                            await release.wait()
                        except asyncio.CancelledError:
                            cancelled.add(human)
                            raise
                        result = (
                            AIMessage(
                                content="result-" + human,
                                usage_metadata={
                                    "input_tokens": 3,
                                    "output_tokens": 2,
                                    "total_tokens": 5,
                                },
                            )
                            if any(isinstance(m, ToolMessage) for m in messages)
                            else AIMessage(
                                content="",
                                tool_calls=[
                                    {
                                        "name": "search_web",
                                        "args": {"query": human},
                                        "id": "same-inner-call",
                                        "type": "tool_call",
                                    }
                                ],
                            )
                        )
                    return ChatResult(generations=[ChatGeneration(message=result)])

            monkeypatch.setenv("RUNTIME_WORKSPACE_ROOT", str(tmp_path))
            monkeypatch.setenv("TAVILY_API_KEY", "synthetic")

