                runtime_context_hash(cfg["context"])
            )
            graph = await agent.get_agent(cfg)
            graph.checkpointer = InMemorySaver()
            events = []

            async def consume():
                async for part in graph.astream(
                    {"messages": [("user", "parent-private-input")]},
                    {**cfg, "callbacks": [Recorder()]},
                    context=cfg["context"],
                    subgraphs=True,
                    stream_mode="updates",
                ):
                    events.append(part)

            execution = asyncio.create_task(consume())
