LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
BEGIN
    IF a=b OR cardinality(b)=0 THEN RETURN a; END IF;
    RETURN ARRAY(SELECT DISTINCT v FROM unnest(a || b) v ORDER BY v LIMIT 51);
END;
